import React from 'react';
import { CancellationForm } from '@oods/components-react';
import { GeneratedUI as List } from './screens/List';
import { GeneratedUI as Detail } from './screens/Detail';
import { GeneratedUI as Form } from './screens/Form';
import { GeneratedUI as Timeline } from './screens/Timeline';
import { createWorkflow, screenProps, collectionEvents, routes, supplementalFields, cancellable, cancellationFormProps, type Screen } from './application';
import type { StoreOptions } from './store';
import './app.css';
export default function App(options: StoreOptions) {
  const [app] = React.useState(() => createWorkflow(options));
  const [state, setState] = React.useState(app.snapshot);
  React.useEffect(() => { const unsubscribe = app.subscribe(setState); void app.navigate('list'); return () => { unsubscribe(); app.dispose(); }; }, [app]);
  const props = { ...screenProps(state.draft), rows: state.records.map(screenProps), events: collectionEvents(state.draft), collectionQuery: state, actions: app.actions, uiState: state.uiState };
  return <main className="workflow-app" data-oods-workflow="Usage" data-screen={state.screen} data-selected-id={state.id} data-route={routes[state.screen]} data-ui-state={state.uiState}>
    <header className="workflow-heading"><div><p className="workflow-eyebrow">USAGE WORKSPACE</p><h1>{state.screen === 'list' ? 'Usages' : String(state.draft["usage_id"])}</h1></div><span className="workflow-mode">Local workspace</span></header>
    <nav aria-label="Workflow screens">{(['list', 'detail', 'form', 'timeline'] as Screen[]).map((screen) => <button type="button" key={screen} aria-current={state.screen === screen ? 'page' : undefined} onClick={() => { void app.navigate(screen); }}>{screen === 'form' ? 'Edit' : screen[0].toUpperCase() + screen.slice(1)}</button>)}</nav>
    {state.error && <p role="alert">{state.error}</p>}
    {state.uiState === 'error' && <button type="button" onClick={() => { void app.retry(); }}>Try again</button>}
    <section aria-label="Usage screen" className="workflow-content" onChangeCapture={(event) => app.edit(event.nativeEvent)}>
      {state.uiState === 'success' && state.screen === 'form' && supplementalFields.map((field) => <div className="workflow-field" key={field.name}><label htmlFor={field.name}>{field.label}</label><input id={field.name} name={field.name} aria-describedby={field.name + "-help"} defaultValue={String((state.draft as Record<string, unknown>)[field.name])} /><small id={field.name + "-help"} className="oods-field-help">{field.help}</small></div>)}
      {state.uiState === 'success' && state.screen === 'detail' && cancellable && state.cancelOpen && <section className="workflow-cancel" aria-label="Cancel subscription">
        <CancellationForm {...cancellationFormProps} reason={String((state.draft as Record<string, unknown>).cancellation_reason ?? '')} reasonCode={String((state.draft as Record<string, unknown>).cancellation_reason_code ?? '')} />
        <label className="workflow-checkbox"><input name="cancel_at_period_end" type="checkbox" defaultChecked={Boolean((state.draft as Record<string, unknown>).cancel_at_period_end)} />Cancel at period end</label>
        <button type="button" onClick={() => { void app.confirmCancellation(); }}>Confirm cancellation</button><button type="button" onClick={() => app.dismissCancellation()}>Keep subscription</button>
      </section>}
      {state.screen === 'list' && <List {...props} key={'list'} />}
      {state.screen === 'detail' && <Detail {...props} key={state.revision + ':' + state.uiState} />}
      {state.screen === 'form' && <form onSubmit={(event) => { event.preventDefault(); app.actions.handleSubmit(); }}><Form {...props} key={state.revision + ':' + state.uiState} /></form>}
      {state.screen === 'timeline' && <Timeline {...props} key={state.revision + ':' + state.uiState} />}
      {state.uiState === 'success' && state.screen === 'detail' && Boolean((state.draft as Record<string, unknown>).is_archived) && <button onClick={() => { void app.restore(); }}>Restore record</button>}
    </section>
    <p className="workflow-notice" role="status">{state.notice}</p>
  </main>;
}

export interface WorkflowActions {
  /* @oods-domain-action handleDelete sha256:e958fc4dbee224e7fa8a18179149f2c767ffe34192f16926cabd8ccb54ea7160 */
  /* @oods-domain-source sha256:5b51d6d668874eeceb4de2326434d8cd762aee730fb9a50bcdcd2b9697a71b6e */
  handleDelete: () => void;
  /* @oods-domain-action handleEdit sha256:182384d13b6b98a724f3da849699c7366e6563e36e5d43b4a0e193875662bc50 */
  /* @oods-domain-source sha256:e0774f642e1a26ebce8a8d9dae8da4a509838d11a3f255381068363bb2920c5a */
  handleEdit: () => void;
  /* @oods-domain-action handleFilter sha256:3caa4ca45751d5f98ecb9ca5b3bad67dae3648851ba5c81266abe239c327333e */
  /* @oods-domain-source sha256:dcd80e5df82a87effadc835ba3ee01b87b8f94956dd248f3916e4caea4eeaee2 */
  handleFilter: (criteria: Record<string, unknown>) => void;
  /* @oods-domain-action handlePageChange sha256:96a80b8c3ce40c07c8848f6f1c89113ff702b20ed4b76f78632453ea8e2c87d8 */
  /* @oods-domain-source sha256:0a8c55c98fd586a66355cacc9e6a93637464d275e70b994fc88514b12079369f */
  handlePageChange: (page: number) => void;
  /* @oods-domain-action handleRowClick sha256:ceae6f55efc7d37856f8f7289091cfbaf7a9e975d11de5d12d3c0cad4486b910 */
  /* @oods-domain-source sha256:40f1128b9a619913b31806b44fb2798a64ee2fe80586edfbd8c637eb690790e1 */
  handleRowClick: (rowId: string) => void;
  /* @oods-domain-action handleSort sha256:7e0b149250c324d6472b9703e8d2a0e89c0ea2a39f11ac7bdfab83da38f9607b */
  /* @oods-domain-source sha256:1d35bd28d115ccb4e75fd245375fc8db7b06af97b029755330560fdbc0a86211 */
  handleSort: (column: string) => void;
  /* @oods-domain-action handleSubmit sha256:2f6aa5a9b7d11a3da9990fa83c008344c4ccae92969fb06db5ed068195a26871 */
  /* @oods-domain-source sha256:2774690c84b88d282fa52995d82608d30054d91e7730e9b770103035c2565545 */
  handleSubmit: () => void;
  /* @oods-domain-action handleViewTimeline sha256:77fdf70710dad3e639537244fdc3c3a64e330b99b0cb1427d79f38c14ebf78fe */
  /* @oods-domain-source sha256:ff23e1f2f34ea61a383aabf23a73f205422002045d7cd5f98aec63fc98ee9b6c */
  handleViewTimeline: () => void;
}

